wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::http_client;
use aap::caps::inference_llm;

struct Node;

fn pct_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let kept: Vec<&ItemVerdict> = selected.entries.iter().filter(|e| e.kept).collect();

        // Enrichment fetch: result is deliberately ignored so output is unchanged.
        let text: String = selected
            .entries
            .iter()
            .map(|e| e.title.as_str())
            .collect::<Vec<_>>()
            .join(" ");
        let text: String = text.chars().take(300).collect();
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            pct_encode(&text)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = String::new();
        for e in &kept {
            prompt.push_str(&format!("- {} ({})\n", e.title, e.summary));
        }

        let overview: String = if kept.is_empty() {
            "No items made today's digest.".to_string()
        } else {
            let resp = inference_llm::infer(
                "Write a brief overview of today's digest in plain text, under 500 characters.",
                &prompt,
                "digest",
            );
            resp.chars().take(600).collect()
        };

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
```

